import RedShell from '../assets/red_shell.svg';
import YellowShell from '../assets/yellow_shell.svg';
import GreenShell from '../assets/green_shell.svg';

export const shellType = [RedShell, YellowShell, GreenShell][
  Math.floor(Math.random() * 3)
];

export const position = [
  [10, 13],
  [40, 20],
  [10, 45],
  [10, 20],
  [25, 25],
  [70, 62],
][Math.floor(Math.random() * 6)];

export const getRandomIntInRange = (min: number, max: number): number =>
  Math.floor(Math.random() * (max - min + 1)) + min;

export const generateShellAmount = (min = 20, max = 100): number =>
  Math.ceil((Math.random() * (max - min) + min) / 10) * 10;
