import {FunctionalComponent } from 'preact';
import { useDispatch, useSelector } from 'react-redux';
import { selectTriviaState, setDialogMode } from '../../slice';

import ShareButton from '../ShareButton';

import Close from '@material-ui/icons/Close';
import WaveSeaweed from '../../assets/wave-seaweed.svg';
import RedCrab from '../../assets/red_crab.mp4';

import styles from './styles.module.scss';

const IncorrectAnswerDialog: FunctionalComponent = () => {
  const dispatch = useDispatch();
  const { trivia } = useSelector(selectTriviaState);

  const closeDialog = (): void => {
    dispatch(setDialogMode(null));
  };

  return (
    <div className={styles.container}>
      <button className={styles.close} onClick={closeDialog}>
        <Close />
      </button>
      <div className={styles.waveSeaweed}>
        <img className={styles.seawedMask} src={WaveSeaweed} alt="" />
        <video className={styles.crab} src={RedCrab} muted loop autoPlay />
      </div>

      <div className={styles.content}>
        <div className={styles.description}>{trivia.fact}</div>
        <a
          href={trivia.readMoreLink}
          className={styles.readMoreLink}
          target="_blank"
          rel="noreferrer"
        >
          read more
        </a>
      </div>
      <ShareButton />
    </div>
  );
};

export default IncorrectAnswerDialog;
